		let y = (int(random(cellCount)) * cellSize) + cellSize / 2;
		let clr = palette[i % palette.length];
		shapes.push(new MovingShape(x, y, cellSize, clr));
	}
}

function draw() {
	background(0);
	for (let i of shapes) {
		i.run();
	}
}

function createGrid() {
	noFill();
	stroke('#ffffff');
	strokeWeight(width * 0.0003);
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let xx = i * cellSize + cellSize / 2;
			let yy = j * cellSize + cellSize / 2;
			square(xx, yy, cellSize);
		}
	}
}

