class MovingShape {
	constructor(x, y, w, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.x0 = x;
		this.y0 = y;
		this.x1 = x;
		this.y1 = y;
		this.timer = 0;
		this.tSpan = 3;
		this.clr = clr;
		this.direction = 0;
		this.pDirection = 0;
		this.rects = [];
	}

	show() {
		noStroke();
		fill(this.clr);
		square(this.x, this.y, this.w);

		for (let i of this.rects) {
			i.run();
		}

		for (let i = 0; i < this.rects.length; i++) {
			let r = this.rects[i];
			if (r.isDead) {
				this.rects.splice(i, 1);
			}
		}
	}

	update() {
		this.timer++;
		if (this.timer % this.tSpan == 0) {
			let span = map(sin(frameCount / 70), -1, 1, 1, 110);
			this.rects.push(new TrailSquare(this.x, this.y, this.w, this.clr, span));
			let nextX;
			let nextY;
			do {
				nextX = this.x;
				nextY = this.y;
				this.direction = int(random(4));
				nextX += this.w * cos(this.direction * (TAU / 4));
				nextY += this.w * sin(this.direction * (TAU / 4));
			} while (
				nextX < 0 || nextX > width ||
				nextY < 0 || nextY > height ||
				(this.direction == ((this.pDirection + 2) % 4))
			)

			this.x = nextX;
			this.y = nextY;
			this.pDirection = this.direction;
		}
	}

	run() {
		this.show();
		this.update();
	}
}

class TrailSquare {
	constructor(x, y, w, clr, span) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.alph = 100;
		this.isDead = false;
		this.clr = color(clr);
		this.t = 0;
		this.tSpan = span;
		this.curW = w;
		this.corner = 0;
	}

	show() {
		strokeWeight(this.w * 0.06);
		this.clr.setAlpha(100);
		stroke(this.clr);
		this.clr.setAlpha(this.alph);
		fill(this.clr);
		square(this.x, this.y, this.curW, this.corner)
	}

	update() {
		this.t++;
		let nrm = norm(this.t, 0, this.tSpan);
		this.alph = lerp(150, 0, nrm ** 0.2);
		this.curW = lerp(this.w, 0, nrm ** 2);
		this.corner = lerp(0, this.w / 2, nrm);
		if (this.t > this.tSpan) {
			this.isDead = true;
		}
	}

	run() {
		this.show();
		this.update();
	}
}

